create or replace view IDQ_PRODUCTION.EKS_CALCULATION.SRMARA_EKS_ITEM_ZSKCASESIZEFOREA_1(
	ITEMID,
	ZSKCASESIZE,
	ITEMPREFIX
) as
SELECT        EKS_CALCULATION.STEKS_LISTINGOVERVIEWMAX.ITEMID, EKS_CALCULATION.STEKS_LISTINGOVERVIEWMAX.CaseSize AS zSKCaseSize,
'8' || REPEAT(0, 6 - length(CAST(CAST(EKS_CALCULATION.STEKS_LISTINGOVERVIEWMAX.CaseSize as decimal(6,0)) as VARCHAR(255))))  || CAST(CAST(EKS_CALCULATION.STEKS_LISTINGOVERVIEWMAX.CaseSize as decimal(6,0)) as VARCHAR(255))  AS ItemPrefix
FROM            EKS_CALCULATION.STEKS_LISTINGOVERVIEWMAX_1 INNER JOIN
                         EKS_CALCULATION.XTEKS_BASICINFO_RECCOUNTRY_1 ON EKS_CALCULATION.STEKS_LISTINGOVERVIEWMAX.LISTINGOVERVIEWID = EKS_CALCULATION.XTEKS_BASICINFO_RECCOUNTRY.LISTINGOVERVIEWID AND
                         EKS_CALCULATION.STEKS_LISTINGOVERVIEWMAX.CaseSize = EKS_CALCULATION.XTEKS_BASICINFO_RECCOUNTRY.casesize AND EKS_CALCULATION.STEKS_LISTINGOVERVIEWMAX.ITEMID = EKS_CALCULATION.XTEKS_BASICINFO_RECCOUNTRY.itemid AND
                         EKS_CALCULATION.STEKS_LISTINGOVERVIEWMAX.ReceivingCountry = EKS_CALCULATION.XTEKS_BASICINFO_RECCOUNTRY.ReceivingCountry AND EKS_CALCULATION.STEKS_LISTINGOVERVIEWMAX.SUPPLIERNO = EKS_CALCULATION.XTEKS_BASICINFO_RECCOUNTRY.SUPPLIERNO
WHERE        (EKS_CALCULATION.XTEKS_BASICINFO_RECCOUNTRY.zIsValidContract = 1) AND (EKS_CALCULATION.XTEKS_BASICINFO_RECCOUNTRY.SK_ITEMID IS NULL)
GROUP BY EKS_CALCULATION.STEKS_LISTINGOVERVIEWMAX.ITEMID, EKS_CALCULATION.STEKS_LISTINGOVERVIEWMAX.CaseSize, '8' || REPEAT(0, 6 - length(CAST(CAST(EKS_CALCULATION.STEKS_LISTINGOVERVIEWMAX.CaseSize as decimal(6,0)) as VARCHAR(255)))) || CAST(CAST(EKS_CALCULATION.STEKS_LISTINGOVERVIEWMAX.CaseSize as decimal(6,0)) as VARCHAR(255));